#!/bin/sh
state=$(git rev-parse --git-path livespec-publication); if test -z "$state"; then echo 'LIVESPEC_PR_REFRESH_HEAD_NO_STATE_DIR: this run publication state directory could not be resolved, so whether the refresh changed the head cannot be read; routing back to proof_capture rather than publishing on an unchecked proof identity' >&2; exit 1; fi; if test ! -f "$state/livespec-pr-refresh-changed"; then echo 'LIVESPEC_PR_REFRESH_HEAD_UNCHANGED: pr_refresh left the publish head as it stood, so the head whose proof was verified is the head publication will mark ready' >&2; exit 0; fi; previous_head=$(cat "$state/livespec-pr-refresh-previous-head" 2>/dev/null || true); previous_base=$(cat "$state/livespec-pr-refresh-previous-base" 2>/dev/null || true); new_base=$(cat "$state/livespec-pr-refresh-new-base" 2>/dev/null || true); new_head=$(cat "$state/livespec-pr-refresh-new-head" 2>/dev/null || true); if test -z "$previous_head" || test -z "$previous_base" || test -z "$new_base" || test -z "$new_head"; then echo 'LIVESPEC_PR_REFRESH_HEAD_NO_DECISION_INPUTS: pr_refresh recorded no previous head, previous base, new base and new head for the refresh it performed, so whether the verified proof still covers the new head cannot be computed; routing back to proof_capture for the changed head' >&2; exit 1; fi; branch="${LIVESPEC_PUBLISH_BRANCH:-}"; if test -z "$branch"; then echo 'LIVESPEC_PR_REFRESH_HEAD_NO_BRANCH: no LIVESPEC_PUBLISH_BRANCH in this script environment, so the pull request carrying the verified record cannot be named; routing back to proof_capture for the changed head' >&2; exit 1; fi; number=$(gh pr list --head "$branch" --state all --json number --jq 'map(.number)|max'); if test $? -ne 0 || test -z "$number" || test "$number" = "null"; then echo "LIVESPEC_PR_REFRESH_HEAD_PR_UNRESOLVED: the forge could not be asked which pull request carries $branch, so the verified record cannot be read; routing back to proof_capture for the changed head" >&2; exit 1; fi; program="${LIVESPEC_SANDBOX_CLAUDE_PLUGINS_ROOT:-$HOME/.claude/plugins}/livespec-carry-forward-decision.py"; if test ! -f "$program"; then echo "LIVESPEC_PR_REFRESH_HEAD_DECISION_PROGRAM_ABSENT: the Dispatcher-materialized carry-forward decision program is not at $program, so whether the verified proof covers the new head cannot be decided; routing back to proof_capture for the changed head" >&2; exit 1; fi; if python3 "$program" --pull-request "$number" --default-branch "${LIVESPEC_STAGE_INPUT_DEFAULT_BRANCH}" --previous-head "$previous_head" --previous-base "$previous_base" --new-base "$new_base" --new-head "$new_head"; then echo "LIVESPEC_PR_REFRESH_HEAD_CARRIED_FORWARD: the carry-forward decision found that the incoming commits of $previous_base..$new_base cannot have affected what the verified proof observed, and posted a carried_forward record naming $new_head; proceeding to pr without re-proving" >&2; exit 0; fi; echo "LIVESPEC_PR_REFRESH_HEAD_CHANGED: pr_refresh republished the publish branch at $new_head and the carry-forward decision was reproof_required, so the verified Proof of Done does not cover the head about to be published; routing back to proof_capture so capture, review and replay run for the changed head. The decision record on pull request #$number names every input that decided it" >&2; exit 1
